func defaultShipcheckSafety(hasMCPBinary bool) shipcheckSafety {
	return shipcheckSafety{
		LocalOnly:              true,
		CredentialFree:         true,
		NoAPICalls:             !hasMCPBinary,
		NoDocsEndpointCalls:    !hasMCPBinary,
		NoGitHubCalls:          !hasMCPBinary,
		NoNPMCalls:             !hasMCPBinary,
		NoHomebrewCalls:        !hasMCPBinary,
		NoPublishing:           true,
		NoSigning:              true,
		NoNotarization:         true,
		NoSecretsRead:          !hasMCPBinary,
		NoProductionWrites:     true,
		ReadOnlyMCP:            true,
		ChildProcessExecuted:   hasMCPBinary,
		ChildProcessSandboxed:  false,
		ChildEnvAllowlisted:    hasMCPBinary,
		CallsGitHub:            false,
		CallsNPM:               false,
		CallsHomebrew:          false,
		Publishes:              false,
		Signs:                  false,
		Notarizes:              false,
		ReadsSecrets:           false,
		WritesProduction:       false,
		OptionalMCPBinaryProof: hasMCPBinary,
	}
}

func checkShipcheckCommandTree(root *cobra.Command) shipcheckCheck {
	check := shipcheckCheck{Name: "command_tree", Passed: true}
	for _, path := range requiredShipcheckCommandPaths() {
		if !shipcheckCommandPathExists(root, path) {
			check.Passed = false
			check.Note = "missing required command path(s)"
			check.Evidence = append(check.Evidence, "missing: "+path)
			continue
		}
		check.Evidence = append(check.Evidence, path)
	}
	if check.Passed {
		check.Note = "required public-preview and read command paths are present"
	}
	return check
}

func requiredShipcheckCommandPaths() []string {
	return []string{
		"about",
		"setup check",
		"docs search",
		"sandbox guide",
		"workflow plan",
		"release plan",
		"credentials plan",
		"mcp config",
		"mcp bundle",
		"benchmark ramp",
		"smoke plan",
		"smoke run",
		"customers list",
		"shipcheck public",
		"payments",
		"charges get",
		"payouts get",
		"funding-events list",
	}
}

func shipcheckCommandPathExists(root *cobra.Command, path string) bool {
	if root == nil {
		return false
	}
	cmd, _, err := root.Find(strings.Fields(path))
	return err == nil && cmd != nil && cmd.Runnable()
}

func checkShipcheckObjectiveSurfaces(root *cobra.Command) shipcheckCheck {
	requiredCommands := map[string]string{
		"agent-friendly output":      "agent-context",
		"presentation command":       "about",
		"setup":                      "setup check",
		"customers":                  "customers list",
		"payments":                   "payments",
		"reconciliation data source": "funding-events list",
		"fraud review":               "customers review get-customer",
		"collections":                "charges resubmit create",
		"reporting":                  "reports",
		"monitoring":                 "tail",
		"sandbox testing":            "sandbox guide",
		"docs search":                "docs search",
		"MCP":                        "mcp config",
		"Ramp benchmark":             "benchmark ramp",
		"release readiness":          "release plan",
	}

	check := shipcheckCheck{Name: "objective_surfaces", Passed: true}
	for label, path := range requiredCommands {
		if !shipcheckCommandPathExists(root, path) {
			check.Passed = false
			check.Note = "missing explicit goal surface(s)"
			check.Evidence = append(check.Evidence, "missing "+label+": "+path)
			continue
		}
		check.Evidence = append(check.Evidence, label+": "+path)
	}

	about := buildAboutPayload()
	if about.Status != "local preview" || about.GeneratedBy != "Printing Press generated" || about.MCPSibling != shipcheckExpectedMCPBinary {
		check.Passed = false
		check.Note = "about metadata does not prove local preview presentation"
		check.Evidence = append(check.Evidence, "missing about metadata")
	} else if shipcheckAboutWordArtRenders(about) {
		check.Evidence = append(check.Evidence, "presentation: about word art with local preview metadata")
	} else {
		check.Passed = false
		check.Note = "about human output does not render required word art"
		check.Evidence = append(check.Evidence, "missing about word art")
	}
	if about.RequiresAuth || about.MakesAPICalls || about.WritesProduction {
		check.Passed = false
		check.Note = "about presentation must stay local and credential-free"
		check.Evidence = append(check.Evidence, "about safety regression")
	}

	requiredWorkflows := map[string]bool{}
	for _, name := range workflowPlanNames() {
		requiredWorkflows[name] = true
	}
	for _, name := range []string{"reconciliation", "fraud-monitoring", "collections", "reporting", "monitoring"} {
		if !requiredWorkflows[name] {
			check.Passed = false
			check.Note = "missing explicit workflow surface(s)"
			check.Evidence = append(check.Evidence, "missing workflow: "+name)
			continue
		}
		check.Evidence = append(check.Evidence, "workflow: "+name)
	}

	if check.Passed {
		check.Note = "explicit goal surfaces are present in the executable CLI"
	}
	sort.Strings(check.Evidence)
	return check
}

func shipcheckAboutWordArtRenders(payload aboutPayload) bool {
	var output bytes.Buffer
	cmd := &cobra.Command{}
	cmd.SetOut(&output)
	if err := printAboutHuman(cmd, payload); err != nil {
		return false
	}
	rendered := output.String()
	return strings.Contains(rendered, "  ____  _____ ____") &&
		strings.Contains(rendered, "STRADDLE CLI") &&
		strings.Contains(rendered, "Status: local preview") &&
		strings.Contains(rendered, "Generator: Printing Press generated")
}

func checkShipcheckWorkflowPlans() shipcheckCheck {
	required := []string{"reconciliation", "fraud-monitoring", "collections", "reporting", "monitoring"}
	available := map[string]bool{}
	for _, name := range workflowPlanNames() {
		available[name] = true
	}
	check := shipcheckCheck{Name: "workflow_plans", Passed: true}
	for _, name := range required {
		if !available[name] {
			check.Passed = false
			check.Note = "missing required workflow plan(s)"
			check.Evidence = append(check.Evidence, "missing: "+name)
			continue
		}
		check.Evidence = append(check.Evidence, name)
	}
	if check.Passed {
		check.Note = "required workflow plans are present"
	}
	return check
}

func checkShipcheckDocsCommandSearch() shipcheckCheck {
	check := shipcheckCheck{Name: "docs_command_search", Passed: true}
	// PATCH: completion-audit-discovery proves explicit helper surfaces resolve through docs command search.
	for _, query := range []string{"workflow plan", "ops guide", "mcp config", "mcp bundle", "benchmark ramp", "tail", "shipcheck public"} {
		matches := rankWhich(whichIndex, query, 1)
		if len(matches) == 0 || matches[0].Entry.Command != query {
			check.Passed = false
			check.Note = "docs search --source commands does not find required helper command(s)"
			check.Evidence = append(check.Evidence, "missing: "+query)
			continue
		}
		check.Evidence = append(check.Evidence, query)
	}
	if check.Passed {
		check.Note = "local helper commands are indexed by docs search --source commands"
	}
	return check
}

func checkShipcheckSafetyContract() shipcheckCheck {
	return shipcheckCheck{
		Name:   "safety",
		Passed: true,
		Note:   "local verifier blocks release actions and production writes; optional MCP proof executes a local child process with an allowlisted environment",
		Evidence: []string{
			"no publish, sign, or notarize",
			"no production writes",
			"parent CLI sends only MCP initialize and tools/list when --mcp-binary is used",
			"child process environment is allowlisted",
			"child process is not sandboxed by this command",
		},
	}
}

type shipcheckPrintingPressConfig struct {
	PrintingPressVersion string `json:"printing_press_version"`
	GeneratorRepository  string `json:"generator_repository"`
	LibraryRepository    string `json:"library_repository"`
	PrinterName          string `json:"printer_name"`
	SpecURL              string `json:"spec_url"`
	SpecPath             string `json:"spec_path"`
	SpecChecksum         string `json:"spec_checksum"`
	MCPBinary            string `json:"mcp_binary"`
}

const (
	shipcheckDocsOpenAPIPath       = "sdks/straddle-docs/docs/api-reference/openapi.json"
	shipcheckGeneratorRepository   = "https://github.com/mvanhorn/cli-printing-press"
	shipcheckLibraryRepository     = "https://github.com/mvanhorn/printing-press-library"
	shipcheckExpectedMCPBinary     = "straddle-pp-mcp"
	shipcheckStrictProvenanceEnv   = "STRADDLE_PP_SHIPCHECK_STRICT_PROVENANCE"
	shipcheckPackagedCLIBinaryName = "straddle-pp-cli"
)

func checkShipcheckProvenance() shipcheckCheck {
	return checkShipcheckProvenanceFromDirs(shipcheckProvenanceSearchDirs())
}

func checkShipcheckProvenanceFromDirs(searchDirs []string) shipcheckCheck {
	check := shipcheckCheck{Name: "provenance"}
	configPath := findShipcheckPrintingPressConfig(searchDirs)
	if configPath == "" {
		check.Note = "missing .printing-press.json next to the CLI source/package"
		return check
	}

	raw, err := os.ReadFile(configPath)
	if err != nil {
		check.Note = "read .printing-press.json: " + err.Error()
		return check
	}
	var config shipcheckPrintingPressConfig
	if err := json.Unmarshal(raw, &config); err != nil {
		check.Note = "parse .printing-press.json: " + err.Error()
		return check
	}

	generator := strings.TrimSpace(config.PrintingPressVersion)
	if generator == "" {
		check.Note = "printing_press_version is required"
		return check
	}
	check.Evidence = append(check.Evidence, "generator: CLI Printing Press "+generator)
	if strings.TrimSpace(config.GeneratorRepository) != shipcheckGeneratorRepository {
		check.Note = ".printing-press.json must identify generator_repository " + shipcheckGeneratorRepository
		check.Evidence = append(check.Evidence, "generator repository: missing or unexpected")
		return check
	}
	check.Evidence = append(check.Evidence, "generator repository: "+shipcheckGeneratorRepository)
	if strings.TrimSpace(config.LibraryRepository) != shipcheckLibraryRepository {
		check.Note = ".printing-press.json must identify library_repository " + shipcheckLibraryRepository
		check.Evidence = append(check.Evidence, "library repository: missing or unexpected")
		return check
	}
	check.Evidence = append(check.Evidence, "library repository: "+shipcheckLibraryRepository)
	if printer := strings.TrimSpace(config.PrinterName); printer != "" {
		check.Evidence = append(check.Evidence, "printer: "+printer)
	}

	docsSource := shipcheckDocsOpenAPISource(config)
	if docsSource == "" {
		check.Note = ".printing-press.json must point spec_path or spec_url at " + shipcheckDocsOpenAPIPath
		check.Evidence = append(check.Evidence, "docs openapi: missing")
		return check
	}
	check.Evidence = append(check.Evidence, "docs openapi: "+shipcheckDocsOpenAPIPath)

	checksum := strings.TrimSpace(config.SpecChecksum)
	if checksum == "" {
		check.Note = "spec_checksum is required"
		check.Evidence = append(check.Evidence, "checksum: missing")
		return check
	}
	expectedHash, ok := strings.CutPrefix(checksum, "sha256:")
	expectedHash = strings.TrimSpace(expectedHash)
	if !ok || !shipcheckValidSHA256Hex(expectedHash) {
		check.Note = "spec_checksum must use sha256:<64 hex characters>"
		check.Evidence = append(check.Evidence, "checksum: invalid format")
		return check
	}

	localSource := shipcheckLocalSourcePath(docsSource)
	if localSource == "" {
		check.Evidence = append(check.Evidence, "checksum: recorded sha256:"+expectedHash)
		check.Evidence = append(check.Evidence, "checksum: source not local, not rehashed")
	} else {
		resolvedSource := resolveShipcheckSourcePath(configPath, localSource)
		actualHash, err := sha256FileHex(resolvedSource)
		if err != nil {
			check.Evidence = append(check.Evidence, "checksum: recorded sha256:"+expectedHash)
			check.Evidence = append(check.Evidence, "checksum: source unavailable, not rehashed")
			if shipcheckStrictProvenance() {
				check.Note = "source OpenAPI file missing or unreadable in strict provenance mode: " + resolvedSource
				return check
			}
		} else {
			if !strings.EqualFold(actualHash, expectedHash) {
				check.Note = "source OpenAPI checksum mismatch"
				check.Evidence = append(check.Evidence, "checksum: mismatch expected sha256:"+expectedHash+" got sha256:"+actualHash)
				return check
			}
			check.Evidence = append(check.Evidence, "checksum: matched sha256:"+actualHash)
		}
	}

	if !checkShipcheckMCPProvenance(configPath, config, &check) {
		return check
	}
	check.Evidence = append(check.Evidence, "generated spec.json: not compared; source checksum is preserved in .printing-press.json")

	check.Passed = true
	if shipcheckEvidenceItemContains(check.Evidence, "checksum: source unavailable") || shipcheckEvidenceItemContains(check.Evidence, "checksum: source not local") {
		check.Note = "Printing Press and docs OpenAPI provenance use recorded checksum evidence; local source was not rehashed"
	} else {
		check.Note = "Printing Press and docs OpenAPI provenance are locally verified"
	}
	return check
}

func shipcheckEvidenceItemContains(evidence []string, want string) bool {
	for _, item := range evidence {
		if strings.Contains(item, want) {
			return true
		}
	}
	return false
}

func shipcheckStrictProvenance() bool {
	value := strings.TrimSpace(os.Getenv(shipcheckStrictProvenanceEnv))
	return value != "" && value != "0" && !strings.EqualFold(value, "false")
}

func shipcheckValidSHA256Hex(value string) bool {
	if len(value) != sha256.Size*2 {
		return false
	}
	decoded, err := hex.DecodeString(value)
	return err == nil && len(decoded) == sha256.Size
}

func checkShipcheckMCPProvenance(configPath string, config shipcheckPrintingPressConfig, check *shipcheckCheck) bool {
	mcpSibling := strings.TrimSpace(config.MCPBinary)
	if mcpSibling == "" {
		check.Note = "mcp_binary is required"
		check.Evidence = append(check.Evidence, "mcp sibling: missing")
		return false
	}
	if mcpSibling != shipcheckExpectedMCPBinary {
		check.Note = "mcp_binary must be " + shipcheckExpectedMCPBinary
		check.Evidence = append(check.Evidence, "mcp sibling: unexpected "+filepath.Base(mcpSibling))
		return false
	}

	configDir := filepath.Dir(configPath)
	if shipcheckBinaryExists(configDir, shipcheckExpectedMCPBinary) {
		check.Evidence = append(check.Evidence, "mcp sibling: "+shipcheckExpectedMCPBinary+" exists next to metadata")
		return true
	}
	if shipcheckBinaryExists(configDir, shipcheckPackagedCLIBinaryName) {
		check.Note = "packaged CLI is missing generated MCP sibling " + shipcheckExpectedMCPBinary
		check.Evidence = append(check.Evidence, "mcp sibling: missing next to packaged CLI")
		return false
	}
	check.Evidence = append(check.Evidence, "mcp sibling: "+shipcheckExpectedMCPBinary+" recorded")
	return true
}

func shipcheckBinaryExists(dir string, name string) bool {
	for _, candidate := range []string{name, name + ".exe"} {
		info, err := os.Stat(filepath.Join(dir, candidate))
		if err == nil && !info.IsDir() {
			return true
		}
	}
	return false
}

func shipcheckProvenanceSearchDirs() []string {
	var cwd string
	if cwd, err := os.Getwd(); err == nil {
		cwd = cwd
	}
	var callerFile string
	if _, file, _, ok := runtime.Caller(0); ok {
		callerFile = file
	}
	var executablePath string
	if executable, err := os.Executable(); err == nil {
		executablePath = executable
	}
	return shipcheckProvenanceSearchDirsFrom(cwd, callerFile, executablePath)
}

func shipcheckProvenanceSearchDirsFrom(cwd string, callerFile string, executablePath string) []string {
	var dirs []string
	if executablePath != "" {
		dirs = append(dirs, filepath.Dir(executablePath))
	}
	if cwd != "" {
		dirs = append(dirs, cwd)
	}
	if callerFile != "" {
		dirs = append(dirs, filepath.Dir(callerFile))
	}
	return dirs
}

func findShipcheckPrintingPressConfig(searchDirs []string) string {
	seen := map[string]bool{}
	for _, dir := range searchDirs {
		for current := filepath.Clean(dir); current != "." && current != string(filepath.Separator); current = filepath.Dir(current) {
			if seen[current] {
				break
			}
			seen[current] = true
			candidate := filepath.Join(current, ".printing-press.json")
			if _, err := os.Stat(candidate); err == nil {
				return candidate
			}
			if filepath.Dir(current) == current {
				break
			}
		}
	}
	return ""
}

func shipcheckDocsOpenAPISource(config shipcheckPrintingPressConfig) string {
	for _, candidate := range []string{config.SpecPath, config.SpecURL} {
		candidate = strings.TrimSpace(candidate)
		if candidate == "" {
			continue
		}
		if shipcheckPointsAtDocsOpenAPI(candidate) {
			return candidate
		}
	}
	return ""
}

func shipcheckPointsAtDocsOpenAPI(value string) bool {
	normalized := filepath.ToSlash(strings.TrimSpace(value))
	if index := strings.IndexAny(normalized, "?#"); index >= 0 {
		normalized = normalized[:index]
	}
	normalized = strings.TrimSuffix(normalized, "/")
	return normalized == shipcheckDocsOpenAPIPath || strings.HasSuffix(normalized, "/"+shipcheckDocsOpenAPIPath)
}

func shipcheckLocalSourcePath(value string) string {
	if strings.Contains(value, "://") {
		return ""
	}
	return value
}

func resolveShipcheckSourcePath(configPath string, sourcePath string) string {
	if filepath.IsAbs(sourcePath) {
		return sourcePath
	}
	return filepath.Clean(filepath.Join(filepath.Dir(configPath), sourcePath))
}

func sha256FileHex(path string) (string, error) {
	contents, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(contents)
	return hex.EncodeToString(sum[:]), nil
}

func checkShipcheckMCPTools(root *cobra.Command, binary string) (shipcheckCheck, error) {
	check := shipcheckCheck{
		Name: "mcp_tools",
		Note: "local stdio MCP initialize plus tools/list only",
	}
	validated, err := validateSmokeMCPBinary(binary)
	if err != nil {
		check.Note = err.Error()
		return check, err
	}

	ctx := context.Background()
	if root != nil {
		ctx = root.Context()
	}
	tools, err := runLocalMCPToolsList(ctx, validated, "straddle-pp-cli-shipcheck")
	if err != nil {
		check.Note = err.Error()
		return check, err
	}
	missing := missingShipcheckMCPTools(tools)
	if len(missing) > 0 {
		check.Note = "local stdio MCP tools/list missing required tool(s): " + strings.Join(missing, ", ")
		check.Evidence = sortedKeys(tools)
		return check, apiErr(fmt.Errorf("MCP tools/list missing required tool(s): %s", strings.Join(missing, ", ")))
	}
	check.Passed = true
	check.Evidence = requiredShipcheckMCPTools()
	return check, nil
}

func runLocalMCPToolsList(ctx context.Context, binary string, clientName string) (map[string]bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	var cancel context.CancelFunc
	ctx, cancel = context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	process := exec.CommandContext(ctx, binary)
	process.Env = smokeMCPProcessEnv()

	stdin, err := process.StdinPipe()
	if err != nil {
		return nil, usageErr(fmt.Errorf("prepare MCP stdin: %w", err))
	}
	stdout, err := process.StdoutPipe()
	if err != nil {
		return nil, usageErr(fmt.Errorf("prepare MCP stdout: %w", err))
	}
	if err := process.Start(); err != nil {
		return nil, usageErr(fmt.Errorf("start MCP binary: %w", err))
	}
	defer func() {
		_ = process.Process.Kill()
		_ = process.Wait()
	}()

	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	encoder := json.NewEncoder(stdin)

	if err := encoder.Encode(map[string]any{
		"jsonrpc": "2.0",
		"id":      1,
		"method":  "initialize",
		"params": map[string]any{
			"protocolVersion": "2024-11-05",
			"capabilities":    map[string]any{},
			"clientInfo": map[string]string{
				"name":    clientName,
				"version": "0",
			},
		},
	}); err != nil {
		return nil, apiErr(fmt.Errorf("write MCP initialize request: %w", err))
	}
	if _, err := readSmokeMCPResponse(scanner, "1"); err != nil {
		return nil, err
	}
	if err := encoder.Encode(map[string]any{
		"jsonrpc": "2.0",
		"method":  "notifications/initialized",
		"params":  map[string]any{},
	}); err != nil {
		return nil, apiErr(fmt.Errorf("write MCP initialized notification: %w", err))
	}
	if err := encoder.Encode(map[string]any{
		"jsonrpc": "2.0",
		"id":      2,
		"method":  "tools/list",
		"params":  map[string]any{},
	}); err != nil {
		return nil, apiErr(fmt.Errorf("write MCP tools/list request: %w", err))
	}
	response, err := readSmokeMCPResponse(scanner, "2")
	if err != nil {
		return nil, err
	}
	return smokeMCPToolNames(response), nil
}

func requiredShipcheckMCPTools() []string {
	return []string{
		"mcp_config",
		"mcp_bundle",
		"docs_search",
		"workflow_plan",
		"release_plan",
		"credentials_plan",
		"smoke_run",
		"setup_check",
		"shipcheck_local",
		"shipcheck_public",
	}
}

func missingShipcheckMCPTools(tools map[string]bool) []string {
	var missing []string
	for _, name := range requiredShipcheckMCPTools() {
		if !tools[name] {
			missing = append(missing, name)
		}
	}
	return missing
}

func sortedKeys(values map[string]bool) []string {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

func renderShipcheckLocalResponse(cmd *cobra.Command, flags *rootFlags, payload shipcheckLocalResponse) error {
	asJSON := flags.asJSON || flags.agent || !isTerminal(cmd.OutOrStdout())
	if asJSON {
		return printJSONFiltered(cmd.OutOrStdout(), payload, flags)
	}
	w := cmd.OutOrStdout()
	status := "failed"
	if payload.Passed {
		status = "passed"
	}
	fmt.Fprintf(w, "Shipcheck local: %s\n", status)
	for _, check := range payload.Checks {
		checkStatus := "failed"
		if check.Passed {
			checkStatus = "passed"
		}
		fmt.Fprintf(w, "  %s: %s", check.Name, checkStatus)
		if check.Note != "" {
			fmt.Fprintf(w, " - %s", check.Note)
		}
		fmt.Fprintln(w)
	}
	return nil
}

func renderShipcheckPublicResponse(cmd *cobra.Command, flags *rootFlags, payload shipcheckPublicResponse) error {
	asJSON := flags.asJSON || flags.agent || !isTerminal(cmd.OutOrStdout())
	if asJSON {
		return printJSONFiltered(cmd.OutOrStdout(), payload, flags)
	}
	w := cmd.OutOrStdout()
	status := "blocked"
	if payload.Ready {
		status = "ready"
	}
	fmt.Fprintf(w, "Shipcheck public: %s\n", status)
	localStatus := "failed"
	if payload.LocalPreviewPassed {
		localStatus = "passed"
	}
	fmt.Fprintf(w, "  local_preview: %s\n", localStatus)
	for _, check := range payload.Checks {
		checkStatus := "failed"
		if check.Passed {
			checkStatus = "passed"
		}
		fmt.Fprintf(w, "  %s: %s", check.Name, checkStatus)
		if check.Note != "" {
			fmt.Fprintf(w, " - %s", check.Note)
		}
		fmt.Fprintln(w)
	}
	if len(payload.NextApprovalSteps) > 0 {
		fmt.Fprintln(w, "Next approval steps:")
		for _, step := range payload.NextApprovalSteps {
			fmt.Fprintf(w, "  - %s\n", step)
		}
	}
	return nil
}
